mic_year_id",$ayid);return response()->json($t->orderBy("term_number")->get());} public function apiSections(Request $r){$cg=$r->get("class_grade");$s=Student::whereNotNull("section")->where("section","!=","");if($cg)$s->where("class_grade",$cg);return response()->json($s->distinct()->orderBy("section")->pluck("section"));} }');
